input.script:
const checkbox = document.querySelector('input[type=checkbox][aria-label*="human"]');
if (checkbox) {
  checkbox.click();
  return { clicked: true, checked: checkbox.checked };
}
return { clicked: false, exists: false };

const inputs = document.querySelectorAll('input');
const result = [];
inputs.forEach(i => result.push({type: i.type, label: i.getAttribute('aria-label'), id: i.id}));
return result;

const frames = document.querySelectorAll('iframe');
const result = [];
frames.forEach(f => result.push({src: f.src, id: f.id, title: f.title, name: f.name}));
return result;

return {
  title: document.title,
  url: window.location.href,
  hasOverlay: !!document.querySelector('#wm-ipp-base, .webcache, #cdzza, [id*=overlay]'),
  bodyText: document.body ? document.body.innerText.substring(0, 500) : 'no body'
};
